# Let's also clip the most extreme outliers in conv3.weight for the most suspicious channels
# Channel 3 and 23 have many extreme values

W_final = {}
for k, v in W_new.items():
    W_final[k] = v.clone()

# Clip conv3.weight for channels 3 and 23 to [-0.7, 0.55] (roughly 0.5% and 99.5% percentiles)
changes_conv3_w = []
for ch in [3, 23]:
    w = W_final['conv3.weight'][ch]
    flat = w.flatten()
    # Clip outliers
    mask_high = w > 0.55
    mask_low = w < -0.7
    if mask_high.any():
        for idx in torch.where(mask_high.flatten())[0]:
            old = w.flatten()[idx].item()
            w.flatten()[idx] = 0.55
            changes_conv3_w.append((ch, idx, old, 0.55))
    if mask_low.any():
        for idx in torch.where(mask_low.flatten())[0]:
            old = w.flatten()[idx].item()
            w.flatten()[idx] = -0.7
            changes_conv3_w.append((ch, idx, old, -0.7))

print(f"conv3.weight changes: {len(changes_conv3_w)} values clipped")
# Show first few
for ch, idx, old, new in changes_conv3_w[:10]:
    print(f"  conv3.weight[{ch}, flat_idx={idx}]: {old:.4f} -> {new:.4f}")

